def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after +)
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (everything after -)
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_components = version_part.split('.')
        major = int(version_components[0])
        minor = int(version_components[1]) if len(version_components) > 1 else 0
        patch = int(version_components[2]) if len(version_components) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            prerelease_parsed = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))
                else:
                    prerelease_parsed.append((1, identifier))
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def sort_key(v):
        index = versions.index(v)
        parsed = parse_version(v)
        major, minor, patch, prerelease_parsed = parsed

        # Versions with pre-release sort before versions without
        if prerelease_parsed is None:
            prerelease_tuple = (1,)  # No pre-release sorts after
        else:
            prerelease_tuple = (0, prerelease_parsed)  # Pre-release sorts before

        return (major, minor, patch, prerelease_tuple, index)

    return sorted(versions, key=sort_key)

